-- Canonical LTS executive-role helper.\ncreate or replace function public.is_executive_officer()\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path=''\nas $$\n  select coalesce((select role in (\n    'president'::public.club_role,\n    'vice_president'::public.club_role,\n    'secretary'::public.club_role,\n    'treasurer'::public.club_role,\n    'sergeant_at_arms'::public.club_role,\n    'admin'::public.club_role\n  ) from public.profiles where id=auth.uid()), false);\n$$;\n